// Same rules and glossary as news Translate; the glossary is read live from the repo so it never drifts.
const r = $('Start').first().json;
const g = $input.first().json;
const fields = r.fields && typeof r.fields === 'object' ? r.fields : {};
const keys = Object.keys(fields).filter(k => String(fields[k] ?? '').trim());
if (!keys.length) throw new Error('bot-translate: no text to translate');
const all = keys.map(k => fields[k]).join(' ');
const detect = s => /[֐-׿]/.test(s) ? 'he' : /[Ѐ-ӿ]/.test(s) ? 'ru' : 'en';
const src = ['he', 'ru', 'en'].includes(r.src_lang) ? r.src_lang : detect(all);
const limits = r.limits || {};
const system = [
  'You translate short texts for Unifight Haifa, a judo club in Haifa, Israel. Languages: Hebrew (he), Russian (ru), English (en).',
  `Context: ${r.context || 'club announcement'}. The input JSON gives source_lang and fields (name -> text).`,
  '', 'Rules:',
  '1. Translate faithfully. Do not add, drop, soften or embellish facts. Tone: a club announcement for parents and athletes.',
  '2. Copy exactly: people\'s names, places, club names, dates, times, all numbers, scores, ages, belt grades and weight categories. Never convert units, round or reformat numbers or times.',
  '3. נבחרת on its own means the club squad: «сборная клуба (нивхерет)», "selected team (nivheret)". Never "national team"; only נבחרת ישראל is Israel\'s national team.',
  '4. Never name children in descriptions of photos or videos.',
  '5. In the source language return each field exactly as given.',
  `6. Respect these maximum lengths in characters: ${JSON.stringify(limits)}.`,
  '7. Club glossary: whenever one of these terms or names appears, use exactly its he/ru/en form and follow its rules.',
  `GLOSSARY: ${JSON.stringify({ rules: g.rules || [], terms: g.terms || {} })}`,
  '', 'Reply with one JSON object and nothing else: {"he": {<same field names>}, "ru": {...}, "en": {...}}',
].join('\n');
const input = JSON.stringify({ source_lang: src, fields: Object.fromEntries(keys.map(k => [k, String(fields[k])])) });
return [{ json: { src_lang: src, keys, fields, limits, system, input } }];

const p = $('Prepare').first().json;
const r = $input.first().json;
const raw = typeof r.content === 'string' ? r.content
  : (r.content?.[0]?.text ?? r.text ?? r.output ?? r.message?.content ?? JSON.stringify(r));
const m = String(raw).match(/\{[\s\S]*\}/);
if (!m) throw new Error('Translation reply is not JSON');
const t = JSON.parse(m[0]);
const warnings = [];
const tr = {};
for (const l of ['he', 'ru', 'en']) {
  tr[l] = {};
  for (const k of p.keys) {
    let v = l === p.src_lang ? String(p.fields[k]) : String(t[l]?.[k] ?? '').trim();
    if (!v) throw new Error(`Translation missing ${l}.${k}`);
    const max = Number(p.limits[k]) || 0;
    if (max && v.length > max) { v = v.slice(0, max - 1).replace(/\s+\S*$/, '') + '…'; warnings.push(`${l.toUpperCase()} ${k}: обрезано до ${max} символов`); }
    tr[l][k] = v;
  }
}
// Numbers and times must survive translation; the author checks names.
const src = p.keys.map(k => p.fields[k]).join(' ');
const nums = [...new Set(src.match(/\d+(?:[.,:]\d+)*/g) || [])];
for (const l of ['he', 'ru', 'en']) {
  const txt = p.keys.map(k => tr[l][k]).join(' ');
  const miss = nums.filter(n => !txt.includes(n));
  if (miss.length) warnings.push(`${l.toUpperCase()}: нет чисел ${miss.join(', ')}`);
}
if (/נבחרת/.test(src) && !/ישראל/.test(src) && /national team/i.test(p.keys.map(k => tr.en[k]).join(' '))) {
  warnings.push('Нивхерет переведена как национальная сборная — исправьте');
}
return [{ json: { src_lang: p.src_lang, tr, warnings } }];
